"""Contract-conforming reference implementation used by the counterexample.

Identical in shape to /source/sample.py except that can_read compares the
requester against the owner, as the README contract requires.
"""


def can_read(requester, owner, public=False):
    return public or (bool(requester) and requester == owner)


def checkout_total(price, quantity):
    if quantity < 0:
        raise ValueError("quantity must not be negative")
    return price * quantity
